/** A console path as the console's own subdomain sees it, rooted at `/`. */
export function toAsgardExternalPath(pathname: string): string {
  if (pathname === asgardRoutePrefix) return '/'
  if (pathname.startsWith(`${asgardRoutePrefix}/`)) return pathname.slice(asgardRoutePrefix.length)

  return pathname
}

